import{z as i,x as B,o as s,c as d,q as r,j as o,D as e,d as t,s as A,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"SSH 密钥认证","description":"","frontmatter":{"title":"SSH 密钥认证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssh-keys-auth.md","filePath":"cs/ssh-keys-auth.md","lastUpdated":1791063341000}'),p={name:"cs/ssh-keys-auth.md"};function h(c,a,S,D,u,F){const n=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="ssh-密钥认证" tabindex="-1">SSH 密钥认证 <a class="header-anchor" href="#ssh-密钥认证" aria-label="Permalink to &quot;SSH 密钥认证&quot;">​</a></h1><div class="epigraph"><p>SSH 用主机钥钉服务器身份，用用户钥或证书代替口令。agent 转发、已知主机文件与授权文件的权限，比再选一种分组密码更能决定这次登录是否被掉包。</p><footer>—— RFC 4251–4254；Ylonen and Lonvick；对照 OpenSSH 的认证模型</footer></div><p>上一课<a href="/cs/tls-attack-history">TLS 攻击史</a>收的是 Web 信道。缺口是<strong>运维信道</strong>：SSH 不走 PKI 浏览器锚，而走 first-contact TOFU 与 <code>authorized_keys</code>。不重写 AEAD。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令登录把<a href="/cs/password-salt">口令与加盐</a>问题搬到每个 sshd。公钥认证：用户持签钥，服务器存公钥。主机钥不匹配应中止——TOFU 在第一次无法防中间人。缺口是信任启动与 agent 的委托范围，不是再讲握手字节。</p><p><span class="marginnote">TOFU（Trust On First Use）翻译一下：第一次连接时你没有任何先验指纹可对，只能选择「相信并记住」；从第二次起才有得比对。它防的是「指纹变了」这件事，防不了「第一次就被换」。像第一次接到陌生号码便记下声音，之后靠声音识人——但第一通电话本身无法验证。</span></p><h3 id="不要转发-agent-到不可信跳板" tabindex="-1">不要转发 agent 到不可信跳板 <a class="header-anchor" href="#不要转发-agent-到不可信跳板" aria-label="Permalink to &quot;不要转发 agent 到不可信跳板&quot;">​</a></h3><p>agent 转发等于把签名能力借出。跳板被占则用户钥被当签具。</p><p><span class="marginnote">RFC 4252 认证。OpenSSH 证书是另一 CA 模型，与 X.509 平行。本课不写暴力破口令的字表。</span></p><p><span class="marginnote">agent 转发的常见误区：以为私钥文件被传到了跳板上。实际私钥始终留在你本机，转发出的是一条「远程进程可以请求本地 agent 代签」的通道——但效果等价于把银行卡和密码一起借给同事：对方不需要拿走卡，能让你刷卡就够了。不可信跳板上任何拿到该 socket 的进程都能以你的身份登录下一跳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分主机认证与用户认证。known_hosts 钉指纹；CA 签主机钥可规模化。权限：<code>.ssh</code> 过宽则密钥文件被换。对照 WireGuard：双方静态钥，模型更简单。</p>',13)),(s(),o(l,null,{default:e(()=>[A(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HK%5B%22%E4%B8%BB%E6%9C%BA%E9%92%A5%20TOFU%2FCA%22%5D%20--%3E%20SESS%5B%22%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%22%5D%0A%20%20UK%5B%22%E7%94%A8%E6%88%B7%E7%AD%BE%E9%92%A5%22%5D%20--%3E%20AUTH%5B%22authorized_keys%22%5D%0A%20%20AUTH%20--%3E%20SESS%0A%20%20AGENT%5B%22agent%22%5D%20-.-%3E%7C%22%E8%BD%AC%E5%8F%91%3D%E5%80%9F%E5%87%BA%E7%AD%BE%E5%90%8D%22%7C%20RISK%5B%22%E8%B7%B3%E6%9D%BF%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"管理面是高价值会话：一次登录等于 root 路径。密钥口令短语与硬件令牌把签钥关进第二因素。下一课 IPsec：网关到网关的 SA，不是交互式 shell。",-1)),(s(),o(l,null,{default:e(()=>[A(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIRST%5B%22%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%BF%9E%E6%8E%A5%EF%BC%9Aknown_hosts%20%E6%97%A0%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20WINDOW%5B%22%E5%94%AF%E4%B8%80%E5%8F%AF%E8%83%BD%E8%A2%AB%E4%B8%AD%E9%97%B4%E4%BA%BA%E9%A1%B6%E6%9B%BF%E6%8C%87%E7%BA%B9%E7%9A%84%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WINDOW%20--%3E%20PIN%5B%22%E8%AE%B0%E5%BD%95%E6%8C%87%E7%BA%B9%EF%BC%9A%E9%92%89%E4%BD%8F%22%5D%0A%20%20PIN%20--%3E%20LATER%5B%22%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%B5%B7%EF%BC%9A%E6%AF%94%E5%AF%B9%E7%8E%B0%E8%BF%9E%E6%8C%87%E7%BA%B9%22%5D%0A%20%20LATER%20--%3E%20SAME%5B%22%E4%B8%80%E8%87%B4%20%E2%86%92%20%E6%94%BE%E8%A1%8C%22%5D%0A%20%20LATER%20--%3E%20DIFF%5B%22%E4%B8%8D%E4%B8%80%E8%87%B4%20%E2%86%92%20%E4%B8%AD%E6%AD%A2%E5%B9%B6%E5%91%8A%E8%AD%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">口令短语与硬件令牌的分工可以这样记：私钥文件像一张卡，口令短语是「用卡的 PIN」，硬件令牌（如 FIDO 密钥）则更进一步——签名操作必须在物理设备里完成，文件被拷走也签不了。三者叠加后，「偷到文件」不再等于「拿到身份」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 KEX 算法列菜单。IPsec 与 IKE 下一课：UDP 上的协商与 SPD。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLS 服务万维网；SSH 钉运维身份。</li><li>主机钥 TOFU 弱在第一次；用户钥代替口令。</li><li>agent 转发是委托，不是免费便利。</li><li>下一课 IPsec 与 IKE。</li><li>出处：RFC 4251–4254；OpenSSH 手册；对照 Anderson 对 TOFU。</li></ul>',5))])}const C=i(p,[["render",h]]);export{T as __pageData,C as default};
